function parseRoleAdminAction(
  value: unknown,
  context: string,
): RoleAdminAction {
  const action = parseString(value, context);
  switch (action) {
    case "create_role":
    case "edit_role":
    case "delete_role":
    case "apply_role":
    case "read_roles":
    case "check_permission":
      return action;
    default:
      throw new Error(
        `${context} must be one of ${ROLE_ADMIN_ACTIONS.join(", ")}`,
      );
  }
}

function parseRoleScopeKindStrict(
  raw: string,
  context: string,
): RoleScope["scope"] {
  switch (raw) {
    case "account":
    case "organization":
    case "project":
      return raw;
    default:
      throw new Error(`${context} must be account, organization, or project`);
  }
}

function parsePrincipalKindStrict(
  raw: string,
  context: string,
): PrincipalRef["principal"] {
  switch (raw) {
    case "account":
    case "role":
      return raw;
    default:
      throw new Error(`${context} must be account or role`);
  }
}

