function parseString(value: unknown, context: string): string {
  if (typeof value !== "string") {
    throw new Error(`${context} must be a string`);
  }
  return value;
}

function parseBoolean(value: unknown, context: string): boolean {
  if (typeof value !== "boolean") {
    throw new Error(`${context} must be a boolean`);
  }
  return value;
}

function parseOptional<TValue>(
  value: unknown,
  context: string,
  parser: (item: unknown, parserContext: string) => TValue,
): TValue | null {
  if (value === null) {
    return null;
  }
  return parser(value, context);
}

function parseArray<TValue>(
  value: unknown,
  context: string,
  parser: (item: unknown, parserContext: string) => TValue,
): TValue[] {
  if (!Array.isArray(value)) {
    throw new Error(`${context} must be an array`);
  }
  return value.map((item, index) => parser(item, `${context}[${index}]`));
}

function expectRecord(
  value: unknown,
  context: string,
): Record<string, unknown> {
  if (!isRecord(value)) {
    throw new Error(`${context} must be an object`);
  }
  return value;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}
